/* Itchy Dragon 81 by Bastimans — https://uiverse.io/Bastimans/itchy-dragon-81 */
button {
  background-color: #ffc600;

  color: #000000;

  padding: 12px 24px;

  border: none;

  border-radius: 30px;

  font-size: 18px;

  font-weight: bold;

  cursor: pointer;

  text-shadow: 2px 2px 3px #ffc600;

  box-shadow: 2px 2px 3px #ffc600;

  transition: all 0.2s ease-in-out;

}

button:hover {
  background-color: #000000;

  color: #ffc600;

  transform: scale(1.1);

}

button:active {
  transform: scale(0.97);
}
